{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.babygo_inventory_fact_items as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(warehouse) as Warehouse, replace(commonsku,\'`\',\'\') sku, SUM(quantity) AS daily_quantity FROM maplemonk.babygo_wh_sales_consolidated WHERE replace(replace(sku,\'-\',\'_\'),\'_\',\'\') is not null and not(order_status = \'CANCELLED\' or oms_order_status = \'CANCELLED\') GROUP BY 1,2,3 ), daily_inventory_snapshot AS ( SELECT DATE(DATETIME_ADD(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',i.Report_Generated_Date), Interval 3 hour)) date_day, replace(i.sku,\'`\',\'\') sku, upper(location) as Warehouse, sum(cast(Available_Quantity as INT64)) as inventory_that_day, CASE WHEN ifnull(sum(cast(Available_Quantity as INT64)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(Available_Quantity as INT64)),0) < 4 THEN 1 ELSE 0 END AS is_oos, \'EASYECOM\' AS source FROM maplemonk.easyecom_easyecom_babygo_inventory_snapshot i GROUP BY 1,2,3 ORDER BY 1 DESC ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.warehouse, FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2023-01-01\', CURRENT_DATE())) AS date_day ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, a.warehouse, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45, source FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku and lower(a.warehouse) = lower(s.warehouse) LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku and lower(a.warehouse) = lower(i.warehouse) order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, warehouse, gs.style_id, gs.lot, gs.category, p.product_name, p.category_name, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45, source FROM sales_metrics s LEFT JOIN ( SELECT * FROM maplemonk.EasyEcom_Easyecom_BabyGo_product_master QUALIFY row_number() OVER (PARTITION BY lower(sku) ORDER BY 1) = 1 ) AS P ON lower(replace(s.sku,\' \',\'\')) = lower(P.sku) LEFT JOIN ( SELECT * FROM ( SELECT sku skucode, CAST(internal_category AS STRING) category, style_id, lot, ROW_NUMBER() OVER ( PARTITION BY REPLACE(sku,\' \',\'\') ORDER BY 1 ) rw FROM `babygo-wh.Maplemonk.gs_sku_master` ) WHERE rw = 1 ) gs ON lower(replace(s.sku,\' \',\'\')) = lower(replace(gs.skucode,\' \',\'\')) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            